export const GROWTH_INSIGHTS: GrowthInsight[] = [
  {
    ...published, slug: 'b2b-ai-search-guide', title: 'A practical guide to AI search for B2B companies', description: 'Connect technical SEO, buyer questions, credible expertise and AI visibility measurement without relying on citation promises.', stage: 'Learn', kind: 'Guide', pillar: 'ai-search',
    intro: 'AI search work is most useful when it improves the information a buyer can find and trust about your business. Start with a specific buying decision, then make your expertise and evidence accessible across the pages that support it.',
    takeaways: ['Research buying decisions before collecting prompts.', 'Make service scope and supporting evidence easy to evaluate.', 'Measure citations, recommendations and opportunities separately.'],
    sections: [
      { heading: 'Start with a buying decision', paragraphs: ['A useful research brief names the buyer, the problem, the alternatives and the constraints. “AI visibility” alone is too broad to guide content. A cybersecurity vendor might focus on security leaders comparing managed detection services; a manufacturer might focus on engineering teams selecting a supplier for a defined tolerance or operating environment.', 'Ask sales which questions appear before a serious evaluation. Group them into problem diagnosis, solution category, supplier comparison, implementation and commercial justification. Keep a record of the original question and the evidence that would help someone answer it.'], example: 'Illustrative research question: “How should a mid-market manufacturer assess a supplier’s ability to support an automation retrofit?” The content brief should cover compatibility, engineering support, implementation risk and procurement evidence.' },
      { heading: 'Establish the technical and editorial foundation', paragraphs: ['Google’s current guidance connects AI visibility to its existing search and quality systems. It does not require special AI markup, a particular page length or llms.txt. For Qognition, the practical response is to prioritize readable, discoverable pages with original substance over a separate set of pages written only for bots.', 'Audit the actual destination a buyer sees. Can they understand the service, identify the intended customer, find relevant proof and take a sensible next step? The same audit should inspect response status, canonical signals, internal links, rendering and accidental indexing restrictions.'] },
      { heading: 'Build a useful evidence set', paragraphs: ['Match evidence to the claim. A delivery process needs a clear description of responsibilities and outputs. A performance claim needs a source, time period, measurement definition and permission to publish. A service comparison needs explicit criteria and an honest account of tradeoffs.', 'If a relevant case study is unavailable, publish a worked example or methodology and label it accurately. Do not recast an unrelated client’s results as proof for a new niche. Expert interviews, original checklists and documented decision frameworks can be useful without invented success metrics.'], bullets: ['One commercial page for the primary service and buyer need.', 'Supporting explanations for implementation, evaluation and cost questions.', 'A consistent company identity and truthful team information.', 'Relevant third-party coverage or references earned through useful work.'] },
      { heading: 'Separate visibility from business impact', paragraphs: ['A page can be cited as a source without the company being recommended. A company can be mentioned without receiving a referral visit. Track these events independently instead of combining them into one ambiguous AI score.', 'Create a fixed set of commercial prompts and record platform, date, market context and repeated observations. Label the sample size. Connect attributable visits to landing-page actions and CRM outcomes where possible, while accepting that a buyer may return later through another channel.'] },
      { heading: 'Choose the next action from the evidence', paragraphs: ['If the page is inaccessible, fix access first. If it is visible but answers the wrong question, revise the content and internal linking. If it attracts relevant visits but few qualified enquiries, examine the offer, proof and conversion path. Each problem calls for a different intervention.', 'Review the work with sales. The most useful result is not merely more mentions, but a clearer route from the right buyer’s research to a well-qualified conversation. No agency can guarantee how a search engine or AI system will rank, cite or recommend a business.'] },
    ], sources: [sources.ai], related: ['ai-search-readiness-checklist', 'measuring-search-ai-and-pipeline', 'choosing-a-b2b-growth-agency'],
  },
  {
    ...published, slug: 'b2b-demand-generation-guide', title: 'Build a B2B demand program around buying intent', description: 'A practical framework for matching paid media, content, landing pages and sales follow-up to the same customer problem.', stage: 'Learn', kind: 'Guide', pillar: 'demand-generation',
    intro: 'A demand program starts with a commercially important customer problem and a credible next step. Channel selection follows that decision. Running more campaigns does not resolve an unclear audience, weak offer or slow sales handoff.',
    takeaways: ['Choose a buyer problem and one primary conversion.', 'Judge traffic by qualified demand and sales acceptance.', 'Agree test budgets and stop conditions before launching.'],
    sections: [
      { heading: 'Write the commercial brief first', paragraphs: ['Define the target company, buyer role, trigger, problem and economic consequence. Distinguish the person who researches from the person who approves the purchase. A technical lead may value implementation detail while a finance sponsor needs a credible explanation of costs and risk.', 'State the offer in one sentence. A useful first step might be an assessment, implementation workshop or specialist consultation. Specify who it is for, what they receive and what happens next. Avoid a vague “free strategy” offer that collects contacts without establishing fit.'] },
      { heading: 'Match the channel to the job', paragraphs: ['Search campaigns can address an explicit request for a solution. LinkedIn can reach defined professional audiences with a relevant problem or account program. Content can help a buying group evaluate the problem before speaking with sales. These are different jobs, so their creative and conversion expectations should differ.', 'Start with a manageable channel mix. A team with limited follow-up capacity should not launch every platform simultaneously. First confirm that the message, landing page, lead delivery and sales response form a working path. Add retargeting only when audience scale and applicable consent support it.'] },
      { heading: 'Build the landing page around the decision', paragraphs: ['The first screen should connect the visitor’s problem with a clear outcome and audience. Follow with the work involved, appropriate proof, qualification information and a low-friction next step. A page for an engineering buyer should answer technical and delivery questions; a page for a managing partner may need to clarify reputation and lead quality.', 'Keep the form proportionate to the offer. Ask for the information needed to respond intelligently, then gather deeper qualification in the conversation. Explain the follow-up and confirm submission only when the request has been accepted by a working delivery path.'], example: 'Illustrative test: compare “Request a supplier-visibility assessment” with “Book a marketing call” for industrial buyers. Evaluate held, qualified conversations rather than button clicks alone.' },
      { heading: 'Define the measurement chain', paragraphs: ['Record the campaign, source page, first known source and conversion event without placing personal data in analytics. Use a shared definition of a qualified enquiry and an accepted opportunity. Sales should supply a reason when a lead is rejected so the team can improve targeting or the offer.', 'Report spend, qualified enquiries, held meetings and opportunity value together. A cheap form submission can be expensive if it never becomes a relevant sales conversation. Separate agency fees, media spend and third-party tools when evaluating acquisition economics.'] },
      { heading: 'Use a decision log', paragraphs: ['Before launching a test, document the hypothesis, audience, creative, budget, primary outcome and conditions for stopping or continuing. Give the sales cycle enough time to produce useful evidence; do not announce a winning revenue result from a handful of clicks.', 'Review one bottleneck at a time. If relevant visitors arrive but do not respond, improve the page or offer. If meetings occur but sales rejects them, revisit targeting and qualification. If accepted opportunities stall, investigate the buying process with sales.'] },
    ], sources: [], related: ['b2b-revenue-systems-guide', 'measuring-search-ai-and-pipeline', 'qognition-growth-methodology'],
  },
  {
    ...published, slug: 'b2b-account-based-marketing-guide', title: 'Turn a target-account list into a useful ABM program', description: 'Prioritize accounts, research buying groups and connect relevant outreach to a measurable sales process.', stage: 'Learn', kind: 'Guide', pillar: 'account-based-marketing',
    intro: 'An account list is an input, not an ABM strategy. The program becomes useful when the team knows why each account fits, what problem matters, who should be involved and what evidence makes contact worthwhile.', takeaways: ['Separate firmographic fit from buying signals.', 'Research a smaller active cohort before scaling the universe.', 'Measure meetings and opportunity progression at account level.'],
    sections: [
      { heading: 'Define fit and disqualification', paragraphs: ['Describe the companies you can help, using revenue model, operating scale, complexity, markets and customer economics. ARR is appropriate for a recurring software business; annual revenue is the clearer measure for many manufacturers and service firms. Headcount is a useful filter, but it is not proof of budget or readiness.', 'Set exclusion rules. An account can be in the right industry but unsuitable because it lacks a viable offer, cannot serve the target market, has no implementation capacity or needs a service outside the team’s expertise. This prevents sales effort being consumed by superficially attractive logos.'] },
      { heading: 'Prioritize a workable cohort', paragraphs: ['Maintain a broad account universe, then select a smaller active cohort that the team can research and follow up properly. Give the highest-fit accounts individual research; group others by a genuine shared problem. Do not generate superficial personalization by inserting names into the same unsupported claim.', 'Capture the reason for prioritization with a source and date. A hiring announcement, market launch or product change can support a relevant conversation. A third-party intent score is a directional signal and should not be described to the prospect as proof that they are buying.'], bullets: ['Account fit and relevant markets.', 'Observed trigger and source.', 'Likely buying group and roles to verify.', 'Useful insight or resource for the first conversation.', 'Owner, next step and suppression status.'] },
      { heading: 'Make the first contact worth reading', paragraphs: ['Lead with a verified observation that matters to the recipient’s role. Explain its possible commercial implication cautiously, then offer a small, useful next step. Do not claim to know their ad budget, internal priorities or AI visibility without evidence.', 'Coordinate email, calls and LinkedIn as one account conversation. Respect objections and suppression across channels. Country-specific contact rules and platform requirements need review before a campaign; a published business email is not universal permission to contact someone.'], example: 'Illustrative opener: “Your new compliance page explains the platform clearly, but the implementation guide does not answer who owns evidence migration. I drafted a short evaluation checklist for that buying question. Would it be useful?” Use only when the observation is true.' },
      { heading: 'Support the whole buying group', paragraphs: ['The first respondent may not own the budget. Prepare role-specific material: an implementation explanation for users, operational risk for the sponsor and a commercial case for the approver. The core facts should remain consistent across those assets.', 'Account-specific landing pages should provide actual research or relevant information. Keep private proposals and confidential account material out of search indexing. A name-swapped page adds little value to either a prospect or a search engine.'] },
      { heading: 'Close the learning loop with sales', paragraphs: ['Track positive responses, meetings held, acceptance by sales, opportunity creation and stage progression. Record no-fit and no-interest reasons. Total touches and open rates are operational signals, not a substitute for business outcomes.', 'Review performance at cohort and account level. Change the audience, message or offer based on the evidence, and preserve the account history so prospects are not re-entered into repetitive sequences after declining.'] },
    ], sources: [], related: ['b2b-revenue-systems-guide', 'professional-services-growth-playbook', 'qognition-growth-methodology'],
  },
  {
    ...published, slug: 'b2b-revenue-systems-guide', title: 'Connect your website, marketing and CRM to the sales process', description: 'Define lead stages, ownership, attribution and reporting so qualified demand has a reliable path into sales.', stage: 'Learn', kind: 'Guide', pillar: 'revenue-systems', intro: 'A revenue system makes the next action clear. It connects a real enquiry to an owner, a response, a qualification decision and an opportunity record. Automation should support that sequence instead of hiding an unclear process.', takeaways: ['Define stages before automating them.', 'Keep submission acceptance separate from email delivery.', 'Connect channel reporting to sales outcomes without overstating attribution.'],
    sections: [
      { heading: 'Agree the language of the pipeline', paragraphs: ['Document what enquiry, qualified lead, accepted opportunity and customer mean in your business. Include the required evidence and the owner of each transition. A contact who downloads a checklist should not automatically become a sales opportunity.', 'Keep lifecycle stages separate from temporary activity states such as “email sent” or “meeting requested.” This makes reporting more stable when outreach tactics change. Give rejected leads a reason code so marketing can distinguish wrong fit from bad timing or poor follow-up.'] },
      { heading: 'Make capture and handoff dependable', paragraphs: ['A form should validate input, preserve useful source context and give a truthful confirmation. The system should record a recoverable submission before treating a notification email as the sole source of truth. Failed delivery needs visible operational handling.', 'Define routing rules for market, service need and account ownership. Assign a backup owner and a response expectation that the team can actually meet. Duplicate contacts should update a coherent history rather than produce conflicting assignments.'], bullets: ['Source page and requested service.', 'Contact details needed for a response.', 'Source and campaign context where available.', 'Lead owner, submission status and next action.', 'A record of consent or contact restrictions when relevant.'] },
      { heading: 'Use automation for clear decisions', paragraphs: ['Begin with high-confidence workflows: notify the owner, acknowledge an accepted request, create a follow-up task and alert someone if the lead is unassigned. Add scoring only when sales can explain why the score changes the next action.', 'Avoid an elaborate scoring model built on assumptions that have never been tested. An account’s fit and a contact’s observed engagement are different signals. Keep both visible so sales can use judgment.'] },
      { heading: 'Measure the customer journey honestly', paragraphs: ['First-touch and last-touch models answer different questions. Self-reported discovery adds another useful perspective. None should be presented as perfect proof that a single channel caused a sale.', 'Define sourced and influenced pipeline, deduplicate opportunities and use one currency and time basis in a report. A pipeline value is not recognized revenue. If a buyer first saw the company in an AI answer and later returned directly, the data may not capture the whole journey.'] },
      { heading: 'Improve the weakest transition', paragraphs: ['Review a small set of operational measures: response time, qualified share, meeting attendance, stage conversion and time spent in stage. Then examine real records behind the numbers with both marketing and sales.', 'A monthly working session should leave the team with specific changes, an owner and a review date. The purpose of the dashboard is to improve decisions, not to accumulate more charts.'] },
    ], sources: [], related: ['measuring-search-ai-and-pipeline', 'b2b-demand-generation-guide', 'choosing-a-b2b-growth-agency'],
  },
  {
    ...published, slug: 'ai-search-readiness-checklist', title: 'The B2B AI search readiness checklist', description: 'An open checklist for technical access, commercial content, evidence, AI monitoring and lead conversion.', stage: 'Learn', kind: 'Checklist', pillar: 'ai-search', intro: 'Use this checklist to identify the next useful improvement. It is a review framework, not a ranking score or a promise that a platform will cite your business. Record evidence and an owner beside each issue.', takeaways: ['Verify access before investing in more pages.', 'Check whether content helps a buyer make a decision.', 'Keep findings, assumptions and missing evidence separate.'], sections: [
      { heading: '1. Confirm the right pages are accessible', paragraphs: ['Check important commercial URLs in the response HTML and in a browser. A visually polished page still needs a working response, useful main content and consistent discovery signals. Test the deployed site, not only a local build.'], bullets: ['The page returns a successful response and shows meaningful content.', 'Canonical and indexing instructions reflect the intended public URL.', 'Internal navigation links to the page through a useful hierarchy.', 'Search crawlers are not accidentally blocked by hosting or security controls.', 'OAI-SearchBot permissions are checked independently from GPTBot training preferences.'] },
      { heading: '2. Review the buyer decision', paragraphs: ['Ask someone unfamiliar with the company to explain the page after reading it. They should be able to identify the audience, the problem, the work involved and the next step. A list of SEO keywords is not a substitute for those answers.'], bullets: ['The service and intended buyer are explicit.', 'Scope, responsibilities and exclusions are understandable.', 'Implementation and evaluation questions are addressed.', 'Claims link to relevant evidence or are framed as a method.', 'The conversion action matches the visitor’s stage.'] },
      { heading: '3. Inspect proof and company information', paragraphs: ['Create a claim register for public numbers, client names and testimonials. Record the evidence, relevant time period and permission to use them. Remove claims that cannot be substantiated rather than replacing them with another plausible-sounding number.'], bullets: ['Company name, website and contact details are consistent.', 'Team expertise is accurately described.', 'Case studies belong to the company and relevant engagement.', 'Examples are labeled as examples, not presented as measured results.', 'Location wording does not imply an office that does not exist.'] },
      { heading: '4. Review programmatic page quality', paragraphs: ['Read several pages side by side. Each should answer a distinct and useful buyer need. Google’s spam policies address both low-value scaled content and similar location pages that funnel visitors onward. A large catalog can exist without publishing every mathematical combination.'], bullets: ['Each published intersection has a specific reason to exist.', 'The content changes meaningfully with the audience or geography.', 'Draft and unsupported combinations are absent from the sitemap.', 'Dates represent real content changes.', 'There is a process to update, consolidate or retire outdated content.'] },
      { heading: '5. Connect monitoring to action', paragraphs: ['Choose a stable set of important queries and prompts, with an explicit market and buyer context. Repeat observations, preserve the sample size and note the platform. Combine this with referral and CRM evidence rather than treating a single generated answer as a performance trend.'], bullets: ['Traditional search and AI-feature visibility are reported separately.', 'Citations, brand mentions and recommendations are distinguished.', 'Relevant visits can reach a functioning enquiry path.', 'A lead owner and follow-up process exist.', 'The review ends with prioritized actions, not just a score.'], example: 'Suggested review record: URL → issue → observed evidence → buyer impact → proposed action → owner → review date.' },
    ], sources: [sources.bots, sources.spam], related: ['b2b-ai-search-guide', 'qognition-growth-methodology', 'measuring-search-ai-and-pipeline'],
  },
  {
    ...published, slug: 'qognition-growth-methodology', title: 'How Qognition connects search visibility with qualified demand', description: 'Our working method for diagnosing growth constraints, agreeing scope, building useful assets and learning from sales outcomes.', stage: 'Evaluate', kind: 'Methodology', pillar: 'revenue-systems', intro: 'Our method starts with the business and a verified baseline. The work combines research, content, campaigns and revenue operations according to the actual constraint, rather than applying every channel to every company.', takeaways: ['Agree the problem and evidence before choosing deliverables.', 'Give every workstream an owner and acceptance criteria.', 'Use sales feedback to improve the next cycle.'], sections: [
      { heading: 'Discovery: establish what is known', paragraphs: ['We begin with the company’s offer, customer economics, sales process and target markets. Existing analytics, CRM records, content and customer conversations help distinguish measured facts from assumptions. Access gaps are recorded explicitly.', 'The output is a shared brief: ideal customers, decision-makers, priority use cases, current baseline, business constraints and the questions the engagement needs to answer. It is also the place to identify unsupported public claims and irrelevant traffic.'] },
      { heading: 'Prioritization: choose a specific starting point', paragraphs: ['We compare opportunities by buyer relevance, commercial value, available evidence, implementation effort and the team’s ability to deliver. A technical outage should not compete with an optional content experiment on equal terms; it needs to be resolved first.', 'The initial scope identifies the page families, campaigns or processes to improve and the evidence required for publication. A broad market catalog can support long-term coverage while the team focuses its editorial effort on a manageable set of useful destinations.'] },
      { heading: 'Execution: make the work reviewable', paragraphs: ['Content briefs explain the audience, question, decision and supporting sources. Pages are checked for clarity, accuracy, accessibility, relevant proof and a working next step. Technical changes include acceptance criteria for status codes, metadata, linking and conversion tracking.', 'For campaigns, the team agrees the audience, offer, spend assumptions and evaluation criteria. For account programs, it agrees qualification, contact rules and handoff ownership. Each workstream should produce something the client can inspect, not merely an activity report.'] },
      { heading: 'Measurement: maintain a clear chain of evidence', paragraphs: ['Search visibility, AI citations, website engagement, qualified enquiries, accepted opportunities and won business remain separate measures. We connect them where the data permits and state the gaps where it does not.', 'We review real enquiries with the sales team to learn whether the right companies and problems are appearing. When a channel produces irrelevant demand, the response may be to narrow the offer or audience rather than increase volume.'] },
      { heading: 'Iteration: improve one important constraint', paragraphs: ['Each review produces a concise decision log: what changed, what the evidence suggests, what remains uncertain and what happens next. Deliverable counts can describe effort, but they do not replace a commercial assessment.', 'The next scope depends on the findings and delivery capacity. An engagement can expand from AI search into demand or ABM when the foundations and follow-up process are ready. The exact deliverables, fees and responsibilities are agreed in the proposal.'] },
    ], sources: [], related: ['choosing-a-b2b-growth-agency', 'measuring-search-ai-and-pipeline', 'ai-search-readiness-checklist'],
  },
  {
    ...published, slug: 'measuring-search-ai-and-pipeline', title: 'Measure search, AI visibility and pipeline without mixing them up', description: 'A measurement framework for search impressions, AI citations, referrals, qualified enquiries and CRM outcomes.', stage: 'Evaluate', kind: 'Guide', pillar: 'revenue-systems', intro: 'A useful dashboard distinguishes discovery from demand and demand from revenue. The measures can be related, but adding them into a single “AI growth” score conceals the decisions the team needs to make.', takeaways: ['Use first-party platform reports where available.', 'Keep AI visibility separate from traffic and revenue.', 'Report denominators, sample sizes and attribution limitations.'], sections: [
      { heading: 'Define the outcome before the metric', paragraphs: ['Start with the commercial question. If the team needs more qualified evaluation conversations, track the number and fit of those conversations. Search impressions help explain discovery, but they do not establish whether a prospective customer understood or trusted the offer.', 'Write definitions for enquiry, qualified enquiry, meeting held, accepted opportunity and closed business. Include the time period and deduplication rules. This prevents different teams from presenting incompatible totals as if they measured the same outcome.'] },
      { heading: 'Use current platform reporting', paragraphs: ['As of September 2026, Google provides a dedicated generative AI performance view in Search Console, with impressions and page, country, device and date dimensions. Google announced worldwide availability on August 31. This complements the overall Search performance view.', 'Bing’s AI Performance reporting includes citation activity and newer preview views for intents, topics, citation share and period comparison. Bing describes citation share as an observational measure, not traffic share, a ranking or a quality score.'], bullets: ['Record the report, date range and filters used.', 'Do not add overlapping overall and AI report totals together.', 'Inspect individual landing pages and relevant markets.', 'Keep third-party estimates visibly separate from first-party data.'] },
      { heading: 'Treat prompt tracking as a sample', paragraphs: ['A prompt monitor observes selected questions under selected conditions. Define the buyer, market, platform and question set before collecting results. Use repeated observations and keep the denominator rather than reporting “we appeared” from a single run.', 'Record whether the page was cited, the company was mentioned or the company was actually recommended. These are different outcomes. Preserve examples to understand context, but do not treat one answer as a durable ranking position.'] },
      { heading: 'Connect visits to the CRM carefully', paragraphs: ['Track referral traffic and on-site conversions, then map accepted leads to CRM opportunities where identifiers and consent allow. Use source-page context and self-reported discovery as complementary evidence. A buyer can discover the company in one place and return through another.', 'Define sourced and influenced pipeline before reporting them. Deduplicate opportunity value across channels. Show actual closed revenue separately and explain whether the amount is booked value, annualized contract value or recognized revenue.'] },
      { heading: 'Use a small weekly and monthly scorecard', paragraphs: ['Weekly operations can focus on accessibility, form delivery, qualified enquiries, response time and campaign issues. Monthly reviews can examine nonbrand search relevance, AI visibility trends, accepted opportunities and content performance.', 'Use trend comparisons with equivalent periods and explain small samples. Where data is missing, state what cannot yet be concluded. The final output should be a decision: repair access, improve the offer, refine content, adjust targeting or change follow-up.'], example: 'Illustrative scorecard: 20 observed prompts × 3 repeats per platform, 12 qualified enquiries, 7 held meetings and 3 accepted opportunities. These are separate sample measures, not a causal claim or a Qognition performance result.' },
    ], sources: [sources.googleReporting, sources.bingReporting], related: ['b2b-ai-search-guide', 'b2b-revenue-systems-guide', 'qognition-growth-methodology'],
  },
  {
    ...published, slug: 'choosing-a-b2b-growth-agency', title: 'How to choose a B2B growth agency for search and demand', description: 'A practical buyer checklist for scope, evidence, delivery ownership, measurement and realistic AI-search claims.', stage: 'Evaluate', kind: 'Guide', pillar: 'demand-generation', intro: 'Choose an agency around the constraint you need to resolve and the evidence it can provide. A large service menu is less useful than a clear explanation of what will change, who will do the work and how you will evaluate it.', takeaways: ['Ask for relevant evidence, not a logo wall alone.', 'Compare scope and responsibilities before comparing retainers.', 'Reject guaranteed rankings, citations or revenue claims.'], sections: [
      { heading: 'Describe the job you need done', paragraphs: ['Write a brief that names your buyers, target markets, offer, sales cycle and current obstacle. “We need growth” is too broad to compare proposals. “Qualified enterprise enquiries do not understand our implementation model” suggests a more specific research, content and conversion problem.', 'Explain what your internal team can own. An agency engagement needs access to expertise, timely approvals and sales feedback. If those inputs are unavailable, a proposal should adapt the scope rather than silently assume they will appear.'] },
      { heading: 'Examine the relevance of the evidence', paragraphs: ['Ask whether a case study reflects the agency’s actual work, the relevant time period and a comparable challenge. Clarify the starting point, scope, constraints and metric definitions. A traffic result for a consumer service does not automatically prove the ability to create enterprise opportunities.', 'A newer niche offering can still be credible when the agency presents a well-researched method and clearly labeled examples. The issue is not the absence of every possible case study; it is whether claims accurately describe the evidence available.'] },
      { heading: 'Compare the work, not just the monthly number', paragraphs: ['Identify included strategy, content, technical implementation, media operations, creative, reporting and client responsibilities. Check asset ownership, tool costs, media budgets, contract term and what happens when priorities change.', 'Ask for a sample deliverable and acceptance criteria. “AI optimization” should translate into understandable work such as improving access, strengthening commercial content, resolving entity ambiguity or monitoring a defined prompt set.'], bullets: ['Named workstream owners and available capacity.', 'Inputs required from your team.', 'Review and implementation process.', 'Commercial and measurement definitions.', 'Exit process and access to your assets.'] },
      { heading: 'Test the agency’s judgment', paragraphs: ['Ask what it would not do first and why. A credible response should connect priorities to your situation. The agency should be able to distinguish a technical problem, an offer problem and a sales follow-up problem instead of prescribing the same content quota to every client.', 'Ask how it treats uncertainty. Search rankings and AI recommendations are controlled by external systems. Useful commitments concern the quality, scope and execution of the work, along with a transparent review process.'] },
      { heading: 'Make the first engagement concrete', paragraphs: ['Agree a focused starting scope, a baseline, decision points and the evidence needed to expand. A diagnostic or initial program should leave you with usable findings and assets, even if you do not continue into a broader retainer.', 'Compare proposals in a shared table and resolve ambiguities before signing. If pipeline is a stated goal, ensure the CRM and sales team can supply the information required to evaluate it.'] },
    ], sources: [], related: ['qognition-growth-methodology', 'measuring-search-ai-and-pipeline', 'b2b-demand-generation-guide'],
  },
];

type SectorBrief = { slug: string; title: string; description: string; audience: string; problem: string; decisions: string[]; content: string[]; example: string; commercial: string; execution: string; qualification: string[]; pillar: GrowthInsight['pillar'] };
const sectorBriefs: SectorBrief[] = [
  { slug: 'b2b-saas-growth-playbook', title: 'A growth playbook for specialist B2B SaaS', description: 'Connect category visibility, implementation questions and sales qualification for software buyers.', pillar: 'ai-search', audience: 'Software buyers often need several forms of confidence before they enter a serious evaluation: the product fits the workflow, implementation is feasible and the commercial model makes sense. Build separate support for the user, technical evaluator and budget owner while keeping the product facts consistent.', problem: 'A product can attract feature-related traffic without helping a buying team decide whether it belongs on a shortlist. Investigate where the current site fails to explain workflow fit, integrations, migration effort or expected responsibilities. Treat generic software traffic as a research signal rather than evidence of a sales opportunity.', decisions: ['Which workflows and company sizes are genuinely supported?', 'What integrations, security reviews and migration work are involved?', 'What is included in onboarding, support and the commercial scope?'], content: ['A use-case page with a realistic workflow and clear suitability criteria.', 'An implementation guide that distinguishes available capabilities from roadmap plans.', 'A comparison framework that states evaluation criteria rather than declaring universal superiority.', 'A commercial FAQ explaining pricing drivers, procurement and rollout responsibilities.'], example: 'Illustrative buyer question: “How should a 200-person services company evaluate a revenue operations platform when it already uses Salesforce?”', commercial: 'Qualify customer size, workflow, existing systems, sponsor, implementation capacity and decision timing. Use ARR only when describing recurring software revenue; distinguish the customer’s contract value from the agency’s fee.', execution: 'Start with one valuable use case, map its buying questions and improve the primary product destination. Connect content engagement to demo quality and accepted opportunities. Add paid or account campaigns after sales can identify which enquiries match the intended workflow.', qualification: ['Supported use case and existing stack', 'Buying role and internal sponsor', 'Implementation resources and evaluation timing'] },
  { slug: 'industrial-manufacturing-growth-playbook', title: 'A growth playbook for industrial manufacturers and suppliers', description: 'Make technical capability, supplier suitability and enquiry quality clearer for industrial buyers.', pillar: 'ai-search', audience: 'An industrial buying group can include engineering, operations, procurement and management. Its members need different information: technical fit, operational reliability, purchasing requirements and commercial risk. A useful website helps them inspect those questions before requesting a quote.', problem: 'A broad equipment catalog can hide the capabilities that make a supplier appropriate for a specific application. Audit whether the site explains material or process suitability, engineering support, limitations and the information needed for a meaningful enquiry. Do not invent certifications, tolerances or regional service capacity.', decisions: ['Which applications and operating conditions fit the capability?', 'What specifications, certifications or validation documents are actually available?', 'What information does the engineering or quotation team need to respond?'], content: ['Application pages that connect a buyer problem to supported capabilities.', 'Technical specification and documentation pages with clear revision ownership.', 'Procurement checklists explaining quote inputs, constraints and evaluation criteria.', 'Regional pages only where delivery, support or market requirements create meaningful differences.'], example: 'Illustrative buyer question: “What should an engineering team ask before choosing a packaging automation partner for an existing production line?”', commercial: 'Use annual revenue and project or repeat-order economics rather than assuming ARR. Qualify application, technical requirements, purchasing role, destination, project timing and the ability to supply. A small number of suitable enquiries may be more valuable than a large pool of unrelated requests.', execution: 'Choose one equipment or application family. Interview the technical team, inspect current enquiries and build a capability page with a practical RFQ path. Review rejected enquiries with sales to identify missing information or misleading search targeting.', qualification: ['Application and technical fit', 'Delivery market and support requirements', 'Procurement timing and RFQ completeness'] },
  { slug: 'professional-services-growth-playbook', title: 'A growth playbook for specialist professional services', description: 'Turn expertise into clear commercial pages and qualified conversations for advisory, legal, accounting and consulting firms.', pillar: 'account-based-marketing', audience: 'Professional-service buyers evaluate expertise, relevance, trust and the way the engagement will work. A managing partner or commercial sponsor needs a clear explanation of the problem, while internal specialists may examine qualifications, approach and the boundaries of the advice.', problem: 'A list of practice areas can be accurate but insufficient for a buyer facing a specific business event. Organize content around that event and the decision it creates. Keep regulated advice within the firm’s actual qualifications and jurisdictional scope; marketing content should not imply a universal professional conclusion.', decisions: ['What business situation makes this service relevant?', 'Which jurisdictions, company types and engagement types are supported?', 'Who provides the work and what information is needed to begin?'], content: ['Practice pages tied to specific corporate needs such as cross-border tax or an ERP implementation.', 'Named expert profiles with verified credentials and relevant experience.', 'Explanations of the engagement process, inputs and decision boundaries.', 'Anonymized or permitted evidence with context and no invented client endorsement.'], example: 'Illustrative buyer question: “How should a finance team prepare for a transfer-pricing advisory engagement across several operating companies?”', commercial: 'Qualify the business problem, jurisdiction, complexity, sponsor and required expertise. Respect confidentiality from the first form. A low-friction enquiry should not ask visitors to submit privileged, medical or commercially sensitive documents.', execution: 'Select a specialist practice and interview the professionals who deliver it. Build content around recurring buyer questions, then offer a bounded consultation or fit assessment. Review lead quality with the practice owner rather than optimizing for the number of form fills alone.', qualification: ['Relevant business issue and service scope', 'Jurisdiction and professional fit', 'Sponsor, confidentiality requirements and timing'] },
  { slug: 'cybersecurity-growth-playbook', title: 'A growth playbook for cybersecurity companies', description: 'Help security buyers evaluate coverage, implementation and operational responsibility with credible content.', pillar: 'demand-generation', audience: 'Security buyers need to understand coverage, implementation and operational accountability. Technical evaluators may examine integrations and response procedures, while executives focus on risk, staffing and procurement. Marketing must present capabilities accurately enough to support both conversations.', problem: 'Generic threat messaging can produce attention without establishing why a specific provider fits the buyer’s environment. Audit whether the site distinguishes monitoring from response, software from managed service, and included capabilities from optional work. Unsupported fear or security guarantees weaken trust.', decisions: ['Which environments, systems and operating models are supported?', 'Who investigates, escalates and responds to an incident?', 'What evidence supports coverage, onboarding and reporting claims?'], content: ['Service comparison pages with clear boundaries and responsibilities.', 'Implementation and integration guides reviewed by technical specialists.', 'Evaluation checklists for MSSP, MDR, application security or compliance buyers.', 'Permitted case evidence that explains the starting environment and actual work.'], example: 'Illustrative buyer question: “What should a lean security team clarify before selecting an MDR provider for a hybrid environment?”', commercial: 'Qualify environment, internal capability, required coverage, sponsor, procurement constraints and onboarding needs. Do not use a broad compliance label as proof that the prospect requires every service or that a purchase guarantees compliance.', execution: 'Choose one buyer scenario, such as augmenting an internal team or securing a specific application environment. Align the landing page, technical content and campaign message. Review opportunities with technical sales so the campaign attracts problems the delivery team can solve.', qualification: ['Environment and capability fit', 'Operational responsibilities and procurement requirements', 'Technical sponsor and implementation readiness'] },
  { slug: 'logistics-supply-chain-growth-playbook', title: 'A growth playbook for logistics and supply-chain businesses', description: 'Build useful visibility around service lanes, handling requirements and buyer qualification.', pillar: 'ai-search', audience: 'Logistics buyers evaluate whether a provider can support the actual movement, handling and coordination their operation needs. Relevant context may include origin and destination, shipment characteristics, service requirements and the division of responsibility between the parties.', problem: 'A location list or “global logistics” claim does not establish service suitability. A buyer needs to know what the provider can handle and what information determines feasibility. Only publish route, facility, certification or temperature-control claims that the business can substantiate.', decisions: ['Which lanes, shipment types and handling requirements are supported?', 'What facilities, partners or service responsibilities are relevant?', 'What information is required for a meaningful quotation or assessment?'], content: ['Capability pages separating freight forwarding, warehousing, 3PL and specialist handling.', 'Lane or regional pages with verified operational relevance.', 'Buyer checklists for documentation, constraints and service evaluation.', 'Supply-chain software pages that explain workflow fit and integrations rather than implying physical logistics services.'], example: 'Illustrative buyer question: “What should a pharmaceutical shipper verify when assessing a cold-chain logistics provider for a Canadian distribution requirement?”', commercial: 'Qualify origin, destination, goods, service needs, frequency, operational constraints and buying role. Do not expose sensitive shipment details through general analytics. Distinguish a one-off transport request from a potentially recurring commercial account.', execution: 'Begin with a real capability and commercially important buyer need. Improve the service page and enquiry fields, then develop a small set of verified regional or lane resources. Use sales feedback to remove traffic for services or locations the operation cannot support.', qualification: ['Shipment or workflow suitability', 'Service area and operational requirements', 'Recurring potential, buying role and timing'] },
  { slug: 'compliance-risk-govtech-growth-playbook', title: 'A growth playbook for compliance, risk and GovTech software', description: 'Connect regulatory context, operational workflows and procurement evidence without overstating compliance outcomes.', pillar: 'ai-search', audience: 'Buyers in compliance, risk and public-sector technology need to understand the problem a product helps manage, how it fits the workflow and what evidence is required for evaluation. Legal, security, procurement and operational stakeholders may assess different parts of the same decision.', problem: 'A product page can name regulations without explaining the supported workflow or the customer’s remaining responsibilities. Clarify the distinction between a tool, an advisory service and an authoritative compliance determination. Regulatory content needs qualified review and current primary sources.', decisions: ['Which workflow and obligation does the product support?', 'What data, integrations and implementation resources are required?', 'What procurement, accessibility or assurance evidence can be provided?'], content: ['Use-case pages showing the task, responsible roles and operational boundaries.', 'Implementation guides for evidence collection, migration and reporting.', 'Jurisdiction-specific explanations only where expert review and current sources are available.', 'Procurement resources that accurately state capabilities and documentation.'], example: 'Illustrative buyer question: “How should a multi-entity company compare evidence-management workflows in a GRC platform?”', commercial: 'Qualify workflow, jurisdiction, internal ownership, procurement process and implementation capacity. Avoid assuming that every public-sector buyer has the same purchasing process or that software alone delivers legal compliance.', execution: 'Choose a specific workflow and obtain subject-matter input. Connect the commercial page to implementation and evaluation resources. Review lead quality by supported use case and procurement readiness rather than collecting broad regulatory traffic with no clear product fit.', qualification: ['Supported workflow and jurisdiction', 'Procurement and assurance requirements', 'Internal owner and implementation resources'] },
  { slug: 'biotech-research-infrastructure-growth-playbook', title: 'A growth playbook for CROs and biotech infrastructure', description: 'Make research capabilities, study fit and technical evaluation easier to assess for specialist buyers.', pillar: 'account-based-marketing', audience: 'Research-service and biotech-infrastructure buyers need to assess technical fit, study requirements, quality expectations and the practical collaboration model. Scientific users, procurement teams and budget sponsors may all need evidence before they can evaluate a provider.', problem: 'Broad scientific terminology can attract readers without explaining what work the organization can actually perform. A useful capability page states the methods, supported work, inputs and limitations at an appropriate level. Claims about validation, accreditation or outcomes must come from verified evidence.', decisions: ['Which study types, methods or infrastructure needs fit the capability?', 'What samples, data, documentation and specialist input are required?', 'How are quality, confidentiality, scope and handoff handled?'], content: ['Capability pages written with the scientific delivery team.', 'Method and evaluation explanations that distinguish established services from research aspirations.', 'Procurement and project-scoping checklists that avoid collecting sensitive study data publicly.', 'Permitted case examples with clear context and limits on generalization.'], example: 'Illustrative buyer question: “What should a biotech team prepare before asking a contract research organization to scope an analytical study?”', commercial: 'Qualify scientific fit, project scope, required evidence, data sensitivity, sponsor and timing. Use secure processes for confidential materials after initial qualification. Do not transform research content into unsupported medical or regulatory advice.', execution: 'Start with one technically coherent capability. Interview experts, review the current enquiry process and create a clear evaluation resource. Build a researched target-account program around that capability and use expert feedback to improve both content and qualification.', qualification: ['Scientific and infrastructure fit', 'Quality, confidentiality and scope requirements', 'Project sponsor and decision timing'] },
  { slug: 'energy-mining-growth-playbook', title: 'A growth playbook for EnergyTech and MiningTech', description: 'Help complex project buyers evaluate application fit, integration, delivery requirements and commercial evidence.', pillar: 'account-based-marketing', audience: 'Energy and mining technology purchases can involve operators, engineering teams, integrators, procurement and commercial sponsors. A useful growth program helps these stakeholders evaluate the same application with evidence appropriate to their roles.', problem: 'A broad sustainability or innovation claim may not explain whether a solution fits the buyer’s operating environment. Separate verified product capabilities from projected benefits. Location content should reflect actual project, delivery or market differences rather than a list of resource-rich regions.', decisions: ['Which operating conditions and applications are supported?', 'How does the solution integrate with existing equipment or workflows?', 'What evidence is available on implementation, service responsibilities and commercial assumptions?'], content: ['Application pages with technical scope and explicit limitations.', 'Implementation resources for integration, support and project responsibilities.', 'Commercial models with clearly labeled assumptions and sensitivity to inputs.', 'Regional resources where qualified research explains genuine operating or procurement differences.'], example: 'Illustrative buyer question: “How should an industrial operator evaluate monitoring technology for an existing energy-intensive site?”', commercial: 'Qualify application, site requirements, integration complexity, sponsor, procurement process and project stage. Do not infer available marketing budget from company scale or claim guaranteed savings from an illustrative model.', execution: 'Choose a defined application and map the buying group. Build the core evaluation content, then prioritize accounts with a verified reason for relevance. Combine search visibility with account conversations and measure progress through meaningful project stages.', qualification: ['Application and operating environment', 'Integration, service and procurement requirements', 'Project sponsor, stage and evaluation timing'] },
];

for (const sector of sectorBriefs) GROWTH_INSIGHTS.push({
  ...published, slug: sector.slug, title: sector.title, description: sector.description, stage: 'Evaluate', kind: 'Sector playbook', pillar: sector.pillar,
  intro: `${sector.description} This playbook is a recommended operating approach, not a claim of measured client results.`,
  takeaways: sector.qualification,
  sections: [
    { heading: 'Understand the buying decision', paragraphs: [sector.audience, sector.problem], bullets: sector.decisions },
    { heading: 'Build content that supports evaluation', paragraphs: ['Choose a primary commercial destination and supporting resources with distinct jobs. The buyer should be able to understand suitability, assess the evidence and know what to do next. Keep the main information open and readable rather than hiding every useful answer behind a form.'], bullets: sector.content, example: sector.example },
    { heading: 'Qualify the commercial opportunity', paragraphs: [sector.commercial, 'Give the sales team a clear reason to accept or reject an enquiry. Record that feedback in the CRM and use it to refine the audience, content and offer. A larger enquiry count is not an improvement if it creates more work for the wrong problems.'], bullets: sector.qualification },
    { heading: 'Run a focused first program', paragraphs: [sector.execution, 'Agree a baseline before publishing or launching campaigns. Check access, conversion tracking and lead delivery. During reviews, separate relevant search visibility from enquiries and opportunities, and identify the next bottleneck with the people responsible for delivery.'] },
    { heading: 'Expand only when the next page earns its place', paragraphs: ['Add a niche, service or regional page when it helps a buyer evaluate a materially different requirement. A structured taxonomy can represent the whole market without turning every combination into a public landing page.', 'Keep a source and review owner for technical or commercial claims. Update the work when capabilities change. Where evidence is incomplete, describe the method or an illustrative example honestly rather than inventing local experience or performance results.'] },
  ], sources: [], related: ['b2b-ai-search-guide', 'qognition-growth-methodology', 'measuring-search-ai-and-pipeline'],
});

export const getGrowthInsight = (slug: string) => GROWTH_INSIGHTS.find((insight) => insight.slug === slug);
export const getPublishedInsightPaths = () => ['/insights', ...GROWTH_INSIGHTS.map((insight) => `/insights/${insight.slug}`)];
